<?php
require_once __DIR__.'/../includes/admin_ui.php';
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM divisions WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$classes=$pdo->query("SELECT id,name FROM classes WHERE status='Active' ORDER BY name")->fetchAll();
$teachers=$pdo->query("SELECT id,first_name,last_name FROM teachers WHERE status='Active' ORDER BY first_name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$id=(int)($_POST['id']??0);$d=[(int)$_POST['class_id'],trim($_POST['name']),($_POST['class_teacher_id']??'')!==''?(int)$_POST['class_teacher_id']:null];if($id){$pdo->prepare("UPDATE divisions SET class_id=?,name=?,class_teacher_id=? WHERE id=?")->execute([...$d,$id]);audit($pdo,'update','Updated division #'.$id);go('divisions.php','Division updated successfully');}$pdo->prepare("INSERT INTO divisions(class_id,name,class_teacher_id) VALUES(?,?,?)")->execute($d);audit($pdo,'create','Created division');go('divisions.php','Division added successfully');}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare("DELETE FROM divisions WHERE id=?")->execute([$id]);audit($pdo,'delete','Deleted division #'.$id);go('divisions.php','Division deleted');}
$rows=$pdo->query("SELECT d.*,c.name class_name,CONCAT(COALESCE(t.first_name,''),' ',COALESCE(t.last_name,'')) teacher_name FROM divisions d JOIN classes c ON c.id=d.class_id LEFT JOIN teachers t ON t.id=d.class_teacher_id ORDER BY c.name,d.name")->fetchAll();
admin_layout('Divisions','Create and assign divisions to classes, including class teachers.');echo '<div class="actions"><button class="btn" data-modal="divisionModal">＋ Add Division</button><a class="btn light" href="classes.php">Back to Classes</a></div></div>';flash();
echo '<div class="card"><div class="toolbar"><input class="search" data-search="#divisionTable" placeholder="Search class or division"><span class="muted">'.count($rows).' divisions</span></div><div class="table-wrap"><table class="table" id="divisionTable"><thead><tr><th>Class</th><th>Division</th><th>Class Teacher</th><th>Actions</th></tr></thead><tbody>';
foreach($rows as $r){echo '<tr><td>'.e($r['class_name']).'</td><td><b>'.e($r['name']).'</b></td><td>'.e(trim($r['teacher_name'])).'</td><td class="actions-cell"><a class="btn light small" href="?edit='.$r['id'].'">Edit</a><a class="btn danger small" data-confirm="Delete this division?" href="?delete='.$r['id'].'">Delete</a></td></tr>';}
echo '</tbody></table></div></div><div class="modal" id="divisionModal"><div class="modal-box"><div class="modal-head"><h2>'.($edit?'Edit Division':'Add Division').'</h2><button class="close">×</button></div><form class="form" method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.e((string)($edit['id']??0)).'"><div class="form-grid"><label>Class<select name="class_id" required><option value="">Select class</option>'.implode('',array_map(fn($c)=>'<option value="'.$c['id'].'"'.(($edit['class_id']??'')==$c['id']?' selected':'').'>'.e($c['name']).'</option>',$classes)).'</select></label><label>Division Name<input name="name" required value="'.e($edit['name']??'').'"></label><label>Class Teacher<select name="class_teacher_id"><option value="">Not assigned</option>'.implode('',array_map(fn($t)=>'<option value="'.$t['id'].'"'.(($edit['class_teacher_id']??'')==$t['id']?' selected':'').'>'.e(trim($t['first_name'].' '.$t['last_name'])).'</option>',$teachers)).'</select></label></div><div class="form-actions"><button type="button" class="btn light close">Cancel</button><button class="btn">'.($edit?'Update Division':'Save Division').'</button></div></form></div></div>';if($edit)echo '<script>document.getElementById("divisionModal").classList.add("show")</script>';admin_end();